// Usage: node tools/generate-simple-uppercase.mjs /path/to/UnicodeData.txt
// Source: https://www.unicode.org/Public/17.0.0/ucd/UnicodeData.txt
import { readFileSync } from "node:fs";
const pairs = readFileSync(process.argv[2], "utf8")
  .trim()
  .split("\n")
  .map((line) => line.split(";"))
  .filter((fields) => parseInt(fields[0], 16) <= 65535 && fields[12]);
process.stdout.write(
  "// Unicode 17.0.0 UnicodeData.txt field 12; Unicode License V3 (THIRD_PARTY_NOTICES.md).\n" +
    "// Generated by tools/generate-simple-uppercase.mjs.\n" +
    "pub fn upper(unit: u16) u16 {\n    return switch (unit) {\n" +
    pairs
      .map((fields) => `        0x${fields[0]} => 0x${fields[12]},\n`)
      .join("") +
    "        else => unit,\n    };\n}\n",
);
